  nom      = "prod"
}

lab.starter:
variable "cidr" {
  default = "10.20.0.0/16"
}

variable "zones" {
  default = ["eu-west-3a", "eu-west-3b"]
}

resource "aws_vpc" "principal" {
  cidr_block = var.cidr
}

lab.solution:
variable "cidr" {
  type        = string
  description = "Plage d'adresses du réseau principal"
  default     = "10.20.0.0/16"
}

variable "zones" {
  type        = list(string)
  description = "Zones de disponibilité utilisées"
  default     = ["eu-west-3a", "eu-west-3b"]
}

resource "aws_vpc" "principal" {
  cidr_block = var.cidr
}

