lab.solution:
terraform {
  required_version = ">= 1.6, < 2.0"
  backend "s3" {
    bucket       = "exemple-etat-terraform"
    key          = "prod/terraform.tfstate"
    region       = "eu-west-3"
    use_lockfile = true
  }
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
  }
}

provider "aws" {
  region = "eu-west-3"
}

variable "api_token" {
  type        = string
  description = "Jeton de l'API, fourni par TF_VAR_api_token"
  sensitive   = true
}

variable "db_password" {
  type        = string
  description = "Mot de passe de la base"
  sensitive   = true
}

resource "aws_security_group" "web" {
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.10/32"]
  }
}

resource "aws_s3_bucket_acl" "medias" {
  bucket = "exemple-medias"
  acl    = "private"
}

resource "aws_db_instance" "base" {
  engine   = "postgres"
  password = var.db_password
}
